	if store == nil || instance == "" {
		return "", nil, ErrBodyStoreRequired
	}
	if body == "" {
		return "", nil, nil
	}
	sum := sha256.Sum256([]byte(body))
	key := "doc:" + hex.EncodeToString(sum[:])
	if err := store.Put(ctx, key, []byte(body)); err != nil {
		// Classified as deployment-level, not per-document. A store that cannot
		// be written to will fail identically for every following document, and
		// falling through to the walk's skip branch would drop each one whole —
		// parent included — while reporting a healthy ingest.
		return "", nil, fmt.Errorf("%w: store passage body: %w", ErrBodyStoreRequired, err)
	}
	return key, &message.StorageReference{
		StorageInstance: instance,
		Key:             key,
		ContentType:     mimeType,
		Size:            int64(len(body)),
	}, nil
}","class":"http://www.ontologyrepository.com/CommonCoreOntologies/Algorithm","handle":"c360.semsource-9da70e.workspace.golang.function.handler-doc-entities-go-putBody"},{"name":"storage_file_test.go","kind":"file","path":"handler/storage_file_test.go","lines":[1,118],"class":"http://www.ontologyrepository.com/CommonCoreOntologies/InformationBearingArtifact","handle":"c360.semsource-9da70e.workspace.golang.file.handler-storage_file_test-go"},{"name":"advertisedState","kind":"function","path":"ui/src/lib/api/workbench.ts","lines":[56,78],"body":"function advertisedState<T>(
