	if c.bodyStore == nil || result == nil || result.Path == "" {
		return nil
	}
	absPath := filepath.Join(root, result.Path)
	content, err := os.ReadFile(absPath)
	if err != nil {
		c.logger.Debug("read source for body offload failed", "path", absPath, "error", err)
		return nil
	}
