	var s Supervisor
	var mu sync.Mutex
	finished := false

	started := make(chan struct{})
	s.Start(context.Background(), nil, func(ctx context.Context) error {
		close(started)
		<-ctx.Done()
		time.Sleep(50 * time.Millisecond) // unwinding after cancellation
		mu.Lock()
		finished = true
		mu.Unlock()
		return ctx.Err()
	})
	<-started

	stopCtx, cancel := context.WithTimeout(context.Background(), 2*time.Second)
	defer cancel()
	s.Stop(stopCtx, nil)

	mu.Lock()
	defer mu.Unlock()
	if !finished {
		t.Error("Stop() returned before the seed finished unwinding")
	}
}","class":"http://www.ontologyrepository.com/CommonCoreOntologies/Algorithm","handle":"c360.semsource-9da70e.workspace.golang.function.internal-seedsup-supervisor_test-go-TestStopWaitsForTheSeed"},{"name":"startedComponent","kind":"function","path":"processor/ast-source/async_seed_integration_test.go","lines":[19,51],"body":"func startedComponent(t *testing.T, watchRoot string) (*Component, func()) {
